113	export async function login(
114	  prev: any,
115	  formData: FormData,
116	): Promise<{ error?: string; needs2fa?: boolean }> {
117	  const parsed = credsSchema.safeParse({
118	    email: formData.get("email"),
119	    password: formData.get("password"),
120	  });
121	  if (!parsed.success) return { error: "Invalid email or password." };
122	
123	  // App-level throttle: 5 attempts / 15 min per email+IP.
124	  const hdrs = await headers();
125	  const ip = (hdrs.get("x-forwarded-for") ?? "").split(",")[0]?.trim() || "unknown";
126	  const rlId = `${parsed.data.email}:${ip}`;
127	  const rl = loginRateLimit(rlId);
128	  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
129	
130	  const user = await db.user.findUnique({ where: { email: parsed.data.email } });
131	  if (!user || !(await bcrypt.compare(parsed.data.password, user.passwordHash))) {
132	    return { error: "Invalid email or password." };
133	  }
134	  if (user.suspended) return { error: "This account is suspended." };
135	
136	  // Two-factor challenge, if enabled on the account.
137	  if (user.totpEnabled) {
138	    const code = String(formData.get("code") ?? "").trim();
139	    if (!code) return { error: "Enter your 2FA code to continue.", needs2fa: true };
140	    if (!(await verifyTotpForUser(user.id, code))) {
141	      return { error: "Invalid 2FA code.", needs2fa: true };
142	    }
143	  }
