169	async function scheduleNode(planRamMB: number) {
170	  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
171	  if (nodes.length === 0) return null;
172	  const loads = await Promise.all(
173	    nodes.map(async (n) => {
174	      const agg = await db.server.findMany({
175	        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
176	        select: { plan: { select: { ramMB: true } } },
177	      });
178	      const used = agg.reduce((s, r) => s + r.plan.ramMB, 0);
179	      return { node: n, free: n.capacityRamMB - used };
180	    })
181	  );
182	  loads.sort((a, b) => b.free - a.free);
183	  const best = loads[0];
184	  if (best.free < planRamMB) return best.node; // oversell guard handled by capacityCheck; still return best
185	  return best.node;
186	}
