18	 * Compute the extra wallet credit a coupon grants for a top-up of `baseCents`.
19	 * PERCENT -> baseCents * value%; FIXED_CENTS / CREDIT_CENTS -> flat `value` cents.
20	 */
21	function couponBonusForTopup(coupon: Coupon, baseCents: number): number {
22	  switch (coupon.kind) {
23	    case "PERCENT":
24	      return Math.round((baseCents * coupon.value) / 100);
25	    case "FIXED_CENTS":
26	    case "CREDIT_CENTS":
27	      return coupon.value;
28	    default:
29	      return 0;
30	  }
