33	/**
34	 * Validate a promo code for the CURRENT user against a top-up of `baseCents` and
35	 * return the bonus that would be credited. Read-only: it never mutates state,
36	 * so it is safe to call both for the live preview (CouponField) and again inside
37	 * `topUp` to compute the real bonus. Enforces active / expiry / scope /
38	 * minAmount / maxRedemptions / firstTimeOnly / one-per-user rules.
39	 */
40	export async function applyCouponToTopup(
41	  code: string,
42	  baseCents: number
43	): Promise<CouponApplyResult> {
44	  const user = await requireUser();
45	  const normalized = String(code ?? "").trim().toUpperCase();
46	  if (!normalized) return { ok: false, error: "Enter a promo code." };
47	
48	  const coupon = await db.coupon.findUnique({ where: { code: normalized } });
49	  if (!coupon || !coupon.active) return { ok: false, error: "That code isn’t valid." };
50	  if (coupon.scope === "ORDER") {
51	    return { ok: false, error: "This code only applies to server orders." };
52	  }
53	  if (coupon.expiresAt && coupon.expiresAt.getTime() < Date.now()) {
54	    return { ok: false, error: "This code has expired." };
55	  }
56	  if (coupon.maxRedemptions !== null && coupon.timesRedeemed >= coupon.maxRedemptions) {
57	    return { ok: false, error: "This code has reached its redemption limit." };
58	  }
59	  if (coupon.minAmountCents !== null && baseCents < coupon.minAmountCents) {
60	    return {
61	      ok: false,
62	      error: `Add at least $${(coupon.minAmountCents / 100).toFixed(2)} to use this code.`,
63	    };
64	  }
65	
66	  // One redemption per user (mirrors the @@unique([couponId,userId]) constraint).
67	  const already = await db.couponRedemption.findUnique({
68	    where: { couponId_userId: { couponId: coupon.id, userId: user.id } },
69	  });
70	  if (already) return { ok: false, error: "You’ve already used this code." };
71	
72	  if (coupon.firstTimeOnly) {
73	    // "First-time" = the user has never received a positive wallet credit before.
74	    const priorCredits = await db.walletTransaction.count({
75	      where: { userId: user.id, amountCents: { gt: 0 } },
76	    });
77	    if (priorCredits > 0) {
78	      return { ok: false, error: "This code is for first-time customers only." };
79	    }
80	  }
81	
82	  const bonusCents = Math.max(0, couponBonusForTopup(coupon, baseCents));
83	  return {
84	    ok: true,
85	    couponId: coupon.id,
86	    code: coupon.code,
87	    bonusCents,
88	    label: describeCoupon(coupon),
89	  };
90	}
