1	/**
2	 * Dependency-free, in-memory sliding-window rate limiter.
3	 *
4	 * Suitable for single-process app-level throttling (login attempts, etc).
5	 * State lives in a module-level Map; on a horizontally-scaled deployment each
6	 * instance limits independently — acceptable for auth-abuse mitigation. A
7	 * background sweep prunes empty buckets so the Map does not grow unbounded.
8	 */
9	
10	type Bucket = number[]; // sorted-ish list of hit timestamps (ms)
11	
12	const buckets = new Map<string, Bucket>();
13	
14	// Persist the Map across HMR / route reloads in dev.
15	const globalForRl = globalThis as unknown as { __nxeonRateLimit?: Map<string, Bucket> };
16	const store: Map<string, Bucket> = globalForRl.__nxeonRateLimit ?? buckets;
17	if (process.env.NODE_ENV !== "production") globalForRl.__nxeonRateLimit = store;
18	
19	export type RateLimitOptions = { max: number; windowMs: number };
20	export type RateLimitResult = { ok: boolean; retryAfterSec: number; remaining: number };
21	
22	/**
23	 * Record and check a hit for `key`. Returns `{ ok, retryAfterSec, remaining }`.
24	 * When `ok` is false the caller should reject and surface `retryAfterSec`.
25	 */
26	export function checkRateLimit(key: string, { max, windowMs }: RateLimitOptions): RateLimitResult {
27	  const now = Date.now();
28	  sweep(now);
29	  const cutoff = now - windowMs;
30	  const hits = (store.get(key) ?? []).filter((t) => t > cutoff);
31	
32	  if (hits.length >= max) {
33	    const oldest = hits[0];
34	    const retryAfterSec = Math.max(1, Math.ceil((oldest + windowMs - now) / 1000));
35	    store.set(key, hits); // persist the pruned window
36	    return { ok: false, retryAfterSec, remaining: 0 };
37	  }
38	
39	  hits.push(now);
40	  store.set(key, hits);
41	  return { ok: true, retryAfterSec: 0, remaining: max - hits.length };
42	}
43	
44	/** Clear the window for a key (e.g. after a successful login). */
45	export function resetRateLimit(key: string): void {
46	  store.delete(key);
47	}
48	
49	/**
50	 * Preset for login throttling: 5 attempts per 15 minutes per identifier.
51	 * Pass a stable identifier such as `${email}:${ip}`.
52	 */
53	export function loginRateLimit(identifier: string): RateLimitResult {
54	  return checkRateLimit(`login:${identifier}`, { max: 5, windowMs: 15 * 60 * 1000 });
55	}
56	
57	// Opportunistic sweep of fully-expired buckets (runs at most once/min, no timer).
58	let lastSweep = 0;
59	function sweep(now: number) {
60	  if (now - lastSweep < 60_000) return;
61	  lastSweep = now;
62	  const maxWindow = 15 * 60 * 1000;
63	  for (const [key, hits] of store) {
64	    if (hits.length === 0 || hits[hits.length - 1] < now - maxWindow) store.delete(key);
65	  }
66	}
