30	/** Generate a random, unambiguous referral code (uppercase). Uniqueness must be
31	 *  enforced by the caller against the DB. */
32	export function generateReferralCode(length = 7): string {
33	  let out = "";
34	  for (let i = 0; i < length; i++) out += CODE_ALPHABET[randomInt(CODE_ALPHABET.length)];
35	  return out;
